insert into public.evidence_sources
(source_type,title_original,source_label_ru,authors,publication,publication_date,url,doi)
values
('исследование','The price of a cigarette: 20 minutes of life?','Исследование University College London в журнале Addiction','Sarah E. Jackson; Martin J. Jarvis; Robert West','Addiction','2024-12-29','https://onlinelibrary.wiley.com/doi/10.1111/add.16757','10.1111/add.16757'),
('исследование','The Benefits of Quitting Smoking at Different Ages','Исследование о пользе отказа в разном возрасте','Thuy T. T. Le; David Mendez; Kenneth E. Warner','American Journal of Preventive Medicine','2024-06-25','https://pubmed.ncbi.nlm.nih.gov/38936681/','10.1016/j.amepre.2024.06.020'),
('систематический обзор','The effectiveness of cognitive behavioral therapy for smoking cessation: A systematic review and meta-analysis','Систематический обзор когнитивно-поведенческой терапии при отказе от курения',null,'Springer Nature',null,'https://pubmed.ncbi.nlm.nih.gov/41047437/',null),
('систематический обзор','Efficacy of digital interventions for smoking cessation by type and method: a systematic review and network meta-analysis','Сетевой метаанализ цифровой помощи при отказе от курения','Shen Li и соавторы','Nature Human Behaviour','2025-09-02','https://www.nature.com/articles/s41562-025-02295-2','10.1038/s41562-025-02295-2'),
('рекомендация','WHO clinical treatment guideline for tobacco cessation in adults','Клиническое руководство ВОЗ по прекращению употребления табака','Всемирная организация здравоохранения','WHO','2024-07-02','https://www.who.int/publications/b/74755',null),
('систематический обзор','Pharmacological and electronic cigarette interventions for smoking cessation in adults: component network meta-analyses','Кокрейновский обзор средств помощи при отказе от курения','Lindson и соавторы','Cochrane Database of Systematic Reviews','2023-09-12','https://www.cochrane.org/evidence/CD015226_how-effective-are-medications-and-e-cigarettes-quitting-smoking-and-what-works-best','10.1002/14651858.CD015226.pub2'),
('систематический обзор','Effect of exercise intervention on smoking cessation: a meta-analysis','Метаанализ физической активности и тяги к курению','Zhou и соавторы','Frontiers in Psychiatry',null,'https://pubmed.ncbi.nlm.nih.gov/37614760/',null),
('систематический обзор','Smoking cessation for improving mental health','Кокрейновский обзор отказа от курения и психического благополучия','Taylor и соавторы','Cochrane Database of Systematic Reviews','2021-03-09','https://www.cochrane.org/evidence/CD013522_does-stopping-smoking-improve-mental-health','10.1002/14651858.CD013522.pub2'),
('систематический обзор','The waterpipe smoking and human health: a systematic review and meta-analysis of 191 observational studies','Систематический обзор влияния кальяна на здоровье','Sepidarkish и соавторы','Systematic Reviews','2025-03-31','https://pubmed.ncbi.nlm.nih.gov/40165261/','10.1186/s13643-025-02799-y'),
('официальный обзор','Hookahs','Обзор Центров по контролю и профилактике заболеваний США о кальяне',null,'CDC',null,'https://www.cdc.gov/tobacco/other-tobacco-products/hookahs.html',null),
('официальный обзор','Health Effects of Vaping','Обзор Центров по контролю и профилактике заболеваний США об электронных сигаретах',null,'CDC','2025-01-31','https://www.cdc.gov/tobacco/e-cigarettes/health-effects.html',null),
('официальный обзор','Vaping and Quitting','Обзор Центров по контролю и профилактике заболеваний США о вейпе и отказе от курения',null,'CDC','2024-05-15','https://www.cdc.gov/tobacco/e-cigarettes/quitting.html',null),
('систематический обзор','Behavioural interventions for smoking cessation: an overview and network meta-analysis','Кокрейновский обзор поведенческой поддержки при отказе от курения','Hartmann-Boyce и соавторы','Cochrane Database of Systematic Reviews','2021-01-04','https://www.cochrane.org/evidence/CD013229_does-behavioural-support-help-people-stop-smoking','10.1002/14651858.CD013229.pub2')
insert into public.evidence_claims
(code,topic,claim_ru,population_ru,limitations_ru,evidence_level,status,last_reviewed_at,review_due_at)
values
('cigarette_life_minutes_2025','риск','По британской популяционной оценке одна выкуренная сигарета в среднем связана примерно с 20 минутами потерянной ожидаемой жизни.','Люди, курящие сигареты; оценка построена на британских данных.','Это средняя популяционная оценка, а не персональный прогноз. Вред не распределяется буквально и линейно по каждой отдельной сигарете; индивидуальный риск существенно различается.','умеренная уверенность','проверено','2026-08-17','2027-02-17'),
('quitting_helps_any_age_2024','польза отказа','Отказ от курения способен заметно увеличить ожидаемую продолжительность жизни даже в старшем возрасте; чем раньше человек прекращает курить, тем больше потенциальная польза.','Взрослые курящие от 35 до 75 лет в моделировании на данных США.','Оценки основаны на таблицах смертности и усреднённых рисках; они не предсказывают срок жизни конкретного человека.','умеренная уверенность','проверено','2026-08-17','2027-02-17'),
('cbt_long_term_2025','поведенческая помощь','Когнитивно-поведенческая терапия повышает вероятность долгосрочного отказа от курения по сравнению с минимальной поддержкой.','Взрослые курящие; 16 рандомизированных исследований, 2531 участник.','Обзор включал исследования разного качества; авторы оценили общую уверенность как умеренную.','умеренная уверенность','проверено','2026-08-17','2027-02-17'),
('personalized_digital_2025','цифровая помощь','Персонализированные цифровые вмешательства в среднем показывают лучшие показатели отказа от курения, чем стандартная помощь, но качество доказательств остаётся от низкого до умеренного.','Участники 152 рандомизированных исследований цифровых программ прекращения курения.','Исследования неоднородны; результаты разных технологий и программ нельзя автоматически переносить на ALIVE.','умеренная уверенность','проверено','2026-08-17','2027-02-17'),
('who_combined_support_2024','лечение','ВОЗ рекомендует сочетать поведенческую поддержку с доказательными лекарственными средствами прекращения употребления табака, когда они подходят человеку.','Взрослые пользователи табака.','ALIVE не назначает препараты и дозировки; конкретный выбор зависит от противопоказаний, доступности и медицинского контекста.','высокая уверенность','проверено','2026-08-17','2027-02-17'),
('cessation_medicines_2023','лечение','Варениклин, цитизин, никотин-заместительная терапия и бупропион имеют доказательства эффективности для прекращения курения; сочетание пластыря с быстродействующей формой НЗТ также эффективно.','Взрослые курящие из рандомизированных исследований.','Эффективность и безопасность конкретного средства не означают, что оно подходит каждому человеку.','высокая уверенность','проверено','2026-08-17','2027-02-17'),
('acute_exercise_craving_2023','тяга','Короткая физическая активность может временно уменьшать тягу к сигарете и часть симптомов отмены.','Курящие люди в исследованиях физических вмешательств.','Движение может помочь пережить конкретную тягу, но само по себе не показало надёжного увеличения долгосрочной частоты отказа.','умеренная уверенность','проверено','2026-08-17','2027-02-17'),
('mental_health_after_quit_2021','психика','В долгосрочной перспективе прекращение курения не связано с ухудшением психического состояния и может сопровождаться снижением тревоги, депрессивных симптомов и стресса.','Более 169 тысяч участников 102 исследований.','Уверенность различалась по показателям: от очень низкой до умеренной; это не обещание улучшения психического состояния конкретному человеку.','умеренная уверенность','проверено','2026-08-17','2027-02-17'),
('hookah_health_2025','кальян','Курение кальяна связано с рядом неблагоприятных последствий для здоровья; свежий обзор 191 наблюдательного исследования обнаружил связи с сердечно-сосудистыми, онкологическими, респираторными и другими исходами.','807174 участника 191 наблюдательного исследования из 24 стран.','Для большинства конкретных исходов качество доказательств в обзоре оценено как низкое или очень низкое; нельзя переводить кальян в точное число «эквивалентных сигарет по вреду».','предварительные данные','проверено','2026-08-17','2027-02-17'),
('hookah_water_not_filter','кальян','Вода в кальяне не делает дым безопасным и не удаляет из него токсичные вещества; длительная сессия может означать очень большой объём вдыхаемого дыма.','Пользователи кальяна.','Объём дыма не равен пропорциональному риску и не должен использоваться как формула «один кальян = N сигарет по вреду».','высокая уверенность','проверено','2026-08-17','2027-02-17'),
('vape_not_harmless_2025','вейп','Аэрозоль электронных сигарет не является безвредным, а долгосрочные последствия вейпинга изучены хуже, чем последствия курения сигарет.','Пользователи электронных сигарет.','Риск вейпа нельзя приравнивать к риску сигарет. Для взрослого курящего полный переход от горючего табака к вейпу — другой сценарий риска, чем двойное употребление.','высокая уверенность','проверено','2026-08-17','2027-02-17'),
('dual_use_not_protection','вейп','Одновременное курение сигарет и использование вейпа не является надёжным способом защитить здоровье; для снижения вреда от курения важно полностью прекратить употребление горючего табака.','Взрослые, одновременно использующие сигареты и электронные сигареты.','Это не означает, что вейп и сигарета одинаковы по риску; речь о том, что сохранение сигарет сохраняет существенный вред.','умеренная уверенность','проверено','2026-08-17','2027-02-17'),
('behavioural_support_2021','поведенческая помощь','Поведенческая поддержка повышает вероятность отказа от курения на шесть месяцев и дольше; персонализация и короткие цифровые сообщения также могут быть полезны.','312 исследований, более 250 тысяч взрослых курящих.','Эффекты отдельных компонентов неодинаковы; сильнее всего подтверждены консультирование и гарантированные финансовые стимулы.','высокая уверенность','проверено','2026-08-17','2027-02-17')
