insert into public.awareness_content
(code,content_type,title_ru,hook_ru,explanation_ru,motivation_ru,caveat_ru,claim_code,product_types,context_tags,published,sort_order)
values
('fact_twenty_minutes','факт','Около двадцати минут за одну сигарету','По современной британской оценке, одна выкуренная сигарета в среднем связана примерно с 20 минутами потерянной ожидаемой жизни.','Это не значит, что после каждой сигареты с твоих часов буквально исчезает двадцать минут. Исследователи перевели накопленный риск курения в понятную среднюю оценку, чтобы масштаб вреда было легче почувствовать.','Двадцать минут — это время, за которое можно познакомиться с человеком, который изменит твою жизнь, придумать важную идею, услышать нужные слова, пройтись с собакой или просто прожить кусок дня, который уже не повторится.','Популяционная оценка на британских данных, а не прогноз для конкретного человека. Индивидуальный риск сильно различается, а вред не распределяется линейно по каждой сигарете.','cigarette_life_minutes_2025',array['cigarette']::text[],array['риск','время','здоровье']::text[],true,10),
('fact_not_too_late','факт','Бросать не поздно даже после десятилетий курения','Польза отказа не исчезает с возрастом: исследование 2024 года показывает заметный выигрыш ожидаемой жизни даже у людей, прекращающих курить после 65 лет.','Чем раньше прекратить, тем больше потенциальная польза, но идея «я слишком долго курил, уже бессмысленно» не соответствует данным.','Прошлое уже нельзя изменить. Следующая сигарета всё ещё относится к будущему — и именно это будущее остаётся в твоём распоряжении.','Это усреднённые оценки на данных населения США, а не обещание конкретного количества лет жизни.','quitting_helps_any_age_2024',array['cigarette']::text[],array['возраст','мотивация','здоровье']::text[],true,20),
('myth_too_late','миф','«Мне уже поздно бросать»','Нет. Чем раньше прекращаешь, тем больше выигрываешь, но польза остаётся и в старшем возрасте.','В моделировании 2024 года даже отказ в 65 и 75 лет в среднем давал положительный выигрыш ожидаемой жизни по сравнению с продолжением курения.','Тебе не нужно возвращать вчерашние годы. Достаточно перестать отдавать зависимости следующие.','Это популяционная модель и не позволяет предсказать продолжительность жизни отдельного человека.','quitting_helps_any_age_2024',array['cigarette']::text[],array['самообман','возраст','мотивация']::text[],true,30),
('myth_willpower_only','миф','«Нужно просто собрать волю в кулак»','Зависимость — не экзамен на характер. Современные рекомендации предлагают сочетать поведенческую поддержку и доказательные средства лечения, а не полагаться только на силу воли.','ВОЗ рекомендует поведенческие вмешательства и ряд лекарственных средств прекращения употребления табака; сочетание подходов повышает вероятность успеха.','Использовать помощь — не слабость. Цель не доказать, что ты способен страдать без поддержки, а реально освободиться.','Конкретные препараты и их применение требуют учёта противопоказаний и инструкции; ALIVE не назначает лечение.','who_combined_support_2024',array['cigarette']::text[],array['лечение','самообман','мотивация']::text[],true,40),
('myth_nrt_relapse','миф','«Никотин-заместительная терапия означает, что я сорвался»','Нет. Никотин-заместительная терапия — один из доказательных способов помощи при прекращении курения и в ALIVE не считается выкуренной сигаретой.','Главная первая граница — между горючим табаком и лечением зависимости. Если твоя конечная цель — свобода от любого никотина, это может быть отдельным следующим этапом.','Не обесценивай отказ от сигареты только потому, что воспользовался инструментом, который создан именно для помощи в отказе.','ALIVE не назначает форму или дозировку НЗТ; используй препарат согласно инструкции или рекомендации специалиста.','cessation_medicines_2023',array['cigarette']::text[],array['лечение','нзт','самообман']::text[],true,50),
('fact_move_through_craving','факт','Движение может помочь пережить тягу прямо сейчас','Метаанализ показывает: кратковременная физическая активность способна уменьшать тягу и часть симптомов никотиновой отмены.','Это делает прогулку или другое простое движение хорошим инструментом конкретного эпизода — не магическим лечением зависимости, а способом пройти ближайшие минуты иначе.','Иногда тебе не нужно «победить курение навсегда». Достаточно не отдать ему следующие несколько минут.','В исследованиях долгосрочная физическая программа сама по себе не дала надёжного увеличения частоты полного отказа.','acute_exercise_craving_2023',array['cigarette']::text[],array['тяга','движение','замена']::text[],true,60),
('myth_mental_health','миф','«Без сигарет мне психологически станет хуже»','В первые дни отмена действительно может быть неприятной. Но долгосрочные данные не показывают ухудшения психического состояния после отказа; напротив, у многих показателей направление изменений было в сторону улучшения.','Кокрейновский обзор обнаружил снижение тревоги, депрессивных симптомов и стресса у прекративших курить по сравнению с продолжавшими. Уверенность различалась по показателям.','Сигарета может обещать тебе спокойствие на ближайшие минуты. Но это не значит, что жизнь без неё психологически беднее или тяжелее.','Это усреднённые результаты исследований и не заменяют помощь при тревожном или депрессивном расстройстве.','mental_health_after_quit_2021',array['cigarette']::text[],array['стресс','психика','самообман']::text[],true,70),
('fact_cbt','факт','Навык можно переучивать, а не только терпеть','Систематический обзор 2025 года показывает, что когнитивно-поведенческая терапия повышает вероятность долгосрочного прекращения курения.','Это поддерживает сам принцип работы с мыслями, ожиданиями и привычными сценариями: зависимое поведение можно не только запрещать, но и постепенно переучивать.','Каждый раз, когда знакомая ситуация заканчивается иначе, ты собираешь новый опыт вместо ещё одного доказательства старой привычки.','ALIVE использует отдельные когнитивно-поведенческие принципы, но не является полноценной психотерапией и не может присвоить себе эффективность клинической КПТ.','cbt_long_term_2025',array['cigarette']::text[],array['перепрошивка','убеждения','обучение']::text[],true,80),
('myth_hookah_water','миф','«Вода очищает кальянный дым»','Нет. Вода не делает кальянный дым безопасным и не удаляет из него токсичные вещества.','При длительной кальянной сессии человек может вдохнуть очень большой объём дыма; кроме табака дополнительный вклад даёт уголь.','Если тебе важны компания, разговор и вечер — всё это можно оставить. Кальян не обязан быть ценой входа в хороший вечер.','Больший объём дыма нельзя переводить в формулу «один кальян равен N сигаретам по вреду». Точный индивидуальный риск так не считается.','hookah_water_not_filter',array['hookah']::text[],array['кальян','самообман','социальное']::text[],true,90),
('fact_hookah_health','факт','Кальян — не безопасный редкий ритуал','Свежий систематический обзор 191 наблюдательного исследования связывает курение кальяна с целым рядом неблагоприятных исходов для здоровья.','Связи обнаружены для сердечно-сосудистых, онкологических, респираторных и других исходов. При этом качество доказательств для большинства конкретных исходов пока низкое или очень низкое.','Редкость ритуала не превращает дым в нейтральное событие. Можно сохранить встречу, вкус вечера и людей — без обязательного курения.','Наблюдательные исследования не позволяют для каждого исхода точно доказать причинность или вычислить индивидуальный риск.','hookah_health_2025',array['hookah']::text[],array['кальян','здоровье','риск']::text[],true,100),
('myth_vape_harmless','миф','«Электронка — это просто пар и почти безвредно»','Нет. Аэрозоль электронных сигарет не является безвредным, а долгосрочные последствия вейпинга всё ещё изучены хуже, чем последствия обычных сигарет.','При этом важно не смешивать разные вопросы: для взрослого курящего полный переход от горючего табака к вейпу — не то же самое, что продолжение курения сигарет или двойное употребление.','Цель ALIVE — не заставить тебя бояться устройства. Цель — чтобы ты видел реальную зависимость и мог выбирать, сколько места никотин вообще занимает в твоём дне.','Нельзя честно присвоить затяжке вейпа точное число «минут жизни» или приравнять её к сигарете по вреду.','vape_not_harmless_2025',array['vape']::text[],array['вейп','самообман','здоровье']::text[],true,110),
('myth_dual_use','миф','«Если я в основном перешёл на вейп, несколько сигарет уже не важны»','Сохранение сигарет сохраняет существенную часть риска от горючего табака. Двойное употребление не считается надёжной стратегией защиты здоровья.','Если вейп используется как мост от сигарет, важная граница — действительно прекратить курить сигареты, а не просто добавить к ним другой продукт.','Снижение числа сигарет может быть этапом. Но ALIVE не должен выдавать промежуточный этап за конечную свободу от курения.','Это не утверждение, что вейп и сигарета одинаковы по риску. Их нельзя механически сравнивать одной единицей вреда.','dual_use_not_protection',array['cigarette','vape']::text[],array['двойное употребление','вейп','сигареты']::text[],true,120),
('fact_personalization','факт','Персональная цифровая помощь выглядит перспективнее общей','Сетевой метаанализ 2025 года показал более высокую частоту отказа у персонализированных цифровых вмешательств по сравнению со стандартной помощью.','Это поддерживает направление ALIVE: не выдавать всем одинаковый список советов, а учиться на контексте и результатах конкретного человека.','Твоя история нужна не для красивой персонализации текста, а чтобы следующий совет всё меньше был случайным.','Качество доказательств было от низкого до умеренного; это не доказательство эффективности конкретно ALIVE.','personalized_digital_2025',array['cigarette']::text[],array['метод','персонализация']::text[],true,130)
