-- ALIVE R1 — стартовая доказательная база и русские пользовательские формулировки.
-- Источник, claim и пользовательская подача разделены. Медицинский смысл не должен зависеть от маркетинговой фразы.

on conflict (url) do update set
  source_label_ru=excluded.source_label_ru,
  publication_date=excluded.publication_date,
  doi=excluded.doi,
  updated_at=now();

on conflict(code) do update set
  claim_ru=excluded.claim_ru,
  limitations_ru=excluded.limitations_ru,
  evidence_level=excluded.evidence_level,
  status='проверено',
  last_reviewed_at=excluded.last_reviewed_at,
  review_due_at=excluded.review_due_at,
  updated_at=now();

-- Claim → source.
select 'cigarette_life_minutes_2025',id,'основной' from public.evidence_sources where url='https://onlinelibrary.wiley.com/doi/10.1111/add.16757'
on conflict do nothing;

-- Пользовательские формулировки. В интерфейсе показывается не title_original, а этот русский слой.
on conflict(code) do update set
  title_ru=excluded.title_ru,
  hook_ru=excluded.hook_ru,
  explanation_ru=excluded.explanation_ru,
  motivation_ru=excluded.motivation_ru,
  caveat_ru=excluded.caveat_ru,
  claim_code=excluded.claim_code,
  product_types=excluded.product_types,
  context_tags=excluded.context_tags,
  published=true,
  sort_order=excluded.sort_order,
  updated_at=now();

-- Примеры контекстной доставки. Не каждая карточка обязана быть привязана к одному триггеру.
on conflict do nothing;
